import * as vscode from "vscode";
import { getRoboDresserViewerHtml } from "./viewerHtml";

/**
 * Owns the single Robo Dresser 3D viewer webview panel. The panel's only
 * content is the iframe generated by `getRoboDresserViewerHtml` — the iframe
 * makes its own network requests directly to the spawned server, so this
 * class needs no message-passing/bridge logic between the panel document and
 * the extension host.
 *
 * `enableScripts: true` IS required, though: VS Code renders a webview panel
 * inside a sandboxed `<iframe>`, and when scripts are disabled that sandbox
 * omits `allow-scripts` — a restriction that a nested `<iframe>` (like the one
 * `getRoboDresserViewerHtml` embeds) inherits from its parent. Without it, the
 * dresser server's own `<script type="module" src="/js/app.js">` (which loads
 * the catalogue and populates the Robots/Tools/Dressed lists) is silently
 * blocked, even though the server itself responds fine — the viewer just
 * never runs any of its own JS.
 *
 * Reachability of the server (Req 4.2) is the caller's responsibility: the
 * caller must verify the Robo_Dresser_Server is reachable before invoking
 * `createOrShow`. This class unconditionally displays the iframe at the given
 * `baseUrl`, or reveals the existing panel if one is already open.
 */
export class RoboDresserViewerPanel {
  private static current: RoboDresserViewerPanel | undefined;
  private static readonly viewType = "roboDresser.viewer";

  private readonly panel: vscode.WebviewPanel;
  private readonly disposables: vscode.Disposable[] = [];

  /**
   * Open a new panel, or reveal the existing one without duplicating
   * (Req 4.3: bring to foreground and give input focus).
   */
  static createOrShow(context: vscode.ExtensionContext, baseUrl: string): void {
    const column = vscode.window.activeTextEditor?.viewColumn ?? vscode.ViewColumn.One;
    if (RoboDresserViewerPanel.current) {
      // preserveFocus defaults to false, so this both brings the panel to the
      // foreground and gives it input focus (Req 4.3).
      RoboDresserViewerPanel.current.panel.reveal(column);
      return;
    }
    const panel = vscode.window.createWebviewPanel(
      RoboDresserViewerPanel.viewType,
      "Robo Dresser",
      column,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );
    RoboDresserViewerPanel.current = new RoboDresserViewerPanel(panel, baseUrl);
  }

  private constructor(panel: vscode.WebviewPanel, baseUrl: string) {
    this.panel = panel;
    this.panel.webview.html = getRoboDresserViewerHtml(baseUrl);
    // Req 4.4: closing the panel leaves the server running. This handler
    // clears only the module-scoped panel reference — it never calls stop()
    // on any process manager (this class holds no such reference at all).
    this.panel.onDidDispose(() => this.dispose(), null, this.disposables);
  }

  private dispose(): void {
    RoboDresserViewerPanel.current = undefined;
    this.panel.dispose();
    while (this.disposables.length) {
      this.disposables.pop()?.dispose();
    }
  }
}
